        scrollAdjustmentTS();
      } catch (e) {
        console.error(e);
      }
    });

    var adjustTimeoutTS;
    $(window).resize(function () {
      clearTimeout(adjustTimeoutTS);
      adjustTimeoutTS = setTimeout(function () {
